html:
{#
  Macros
  fix_lig: reemplaza ligaturas Unicode (fi, fl, ff, ffi, ffl) que se
  copian de Word/PDF y se ven como '&' en wkhtmltopdf
#}
{%- macro fix_lig(t) -%}{{ t | replace('\ufb01','fi') | replace('\ufb02','fl') | replace('\ufb00','ff') | replace('\ufb03','ffi') | replace('\ufb04','ffl') }}{%- endmacro -%}

{%- set company = frappe.get_doc('Company', doc.company) if doc.company else None -%}
{%- set owner_name = frappe.db.get_value('User', doc.owner, 'full_name') if doc.owner else '' -%}
{%- set owner_email = frappe.db.get_value('User', doc.owner, 'email') if doc.owner else '' -%}
{%- set scope_rows = doc.quotation_scope_items | selectattr('include_in_proposal') | list -%}
{%- set has_designation = scope_rows | selectattr('designation') | list | length > 0 -%}
{%- set has_activity = scope_rows | selectattr('activity_type') | list | length > 0 -%}

<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 10pt; color: #2c2c2c; }
  @page { margin: 1.5cm; }

  /* ── Portada ─────────────────────────────── */
  .cover { page-break-after: always; padding: 20px 0; }
  .cover-header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #1a1a2e; padding-bottom: 16px; margin-bottom: 40px; }
  .company-name-text { font-size: 14pt; font-weight: bold; color: #1a1a2e; }
  .cover-badge { background: #1a1a2e; color: #fff; font-size: 8pt; font-weight: bold; letter-spacing: 2px; text-transform: uppercase; padding: 6px 14px; border-radius: 2px; white-space: nowrap; }
  .cover-title { text-align: center; padding: 40px 0 36px; border-bottom: 1px solid #ddd; margin-bottom: 36px; }
  .cover-title h1 { font-size: 24pt; font-weight: bold; color: #1a1a2e; line-height: 1.25; margin-bottom: 10px; }
  .cover-title .project-ref { font-size: 9pt; color: #888; }
  .cover-parties { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 36px; }
  .cover-party { background: #f8f9fc; border-left: 4px solid #1a1a2e; padding: 16px 18px; }
  .party-label { font-size: 7pt; font-weight: bold; color: #1a1a2e; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 6px; }
  .party-name { font-size: 11pt; font-weight: bold; color: #1a1a2e; margin-bottom: 4px; }
  .party-detail { font-size: 8.5pt; color: #555; line-height: 1.5; }
  .cover-meta { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; border-top: 1px solid #ddd; padding-top: 20px; }
  .meta-label { font-size: 7pt; font-weight: bold; color: #aaa; text-transform: uppercase; letter-spacing: 0.5px; }
  .meta-value { font-size: 10pt; font-weight: bold; color: #1a1a2e; margin-top: 2px; }
  .confidential-banner { background: #fff8e6; border: 1px solid #f0c060; text-align: center; padding: 6px; font-size: 7.5pt; color: #7a4000; font-weight: bold; letter-spacing: 1px; margin-top: 20px; }

  /* ── Secciones narrativas ─────────────────── */
  .section { margin-bottom: 28px; }
  h2.section-title { font-size: 11pt; font-weight: bold; color: #fff; background: #1a1a2e; padding: 7px 12px; margin-bottom: 14px; }
  .section-content { font-size: 9.5pt; line-height: 1.65; color: #333; }
  .section-content p { margin-bottom: 8px; }
  .section-content ul, .section-content ol { padding-left: 20px; margin-bottom: 8px; }
  .section-content li { margin-bottom: 3px; }
  .section-content h3, .section-content h4 { color: #1a1a2e; margin: 10px 0 6px; font-size: 10pt; }
  .section-content table { width: 100%; border-collapse: collapse; margin: 8px 0 12px; font-size: 8.5pt; }
  .section-content table th { background: #e8edf8; color: #1a1a2e; padding: 5px 8px; text-align: left; border: 1px solid #ccd; font-weight: bold; }
  .section-content table td { padding: 5px 8px; border: 1px solid #dde; vertical-align: top; }
  .section-content table tr:nth-child(even) td { background: #f8f9fc; }

  /* ── Plan de Trabajo ─────────────────────── */
  table.deploy-table { width: 100%; border-collapse: collapse; font-size: 8.5pt; margin-top: 2px; }
  table.deploy-table th { background: #1a1a2e; color: #fff; padding: 6px 9px; text-align: left; font-size: 8pt; }
  table.deploy-table th.right, table.deploy-table td.right { text-align: right; }
  table.deploy-table td { padding: 5px 9px; border-bottom: 1px solid #eee; vertical-align: top; }
  tr.phase-row td { background: #e8edf8; font-weight: bold; font-size: 9.5pt; color: #1a1a2e; border-top: 3px solid #1a1a2e; padding: 7px 9px; }
  tr.phase-total td { background: #f4f6fb; font-style: italic; border-top: 1px solid #ccd; font-size: 8pt; }
  table.deploy-table tfoot td { background: #1a1a2e; color: #fff; font-weight: bold; padding: 7px 9px; font-size: 9pt; }
  td.task-cell { padding-left: 20px; }
  .task-desc { font-size: 7.5pt; color: #777; margin-top: 3px; line-height: 1.4; }

  /* ── Entregables ─────────────────────────── */
  .deliverable-item { margin-bottom: 12px; padding: 10px 14px; border-left: 3px solid #1a1a2e; background: #fafbff; page-break-inside: avoid; }
  .deliverable-title { font-size: 9.5pt; font-weight: bold; color: #1a1a2e; margin-bottom: 6px; }
  .deliverable-body { font-size: 8.5pt; color: #444; line-height: 1.55; }
  .deliverable-body p { margin-bottom: 4px; }
  .deliverable-body ul, .deliverable-body ol { padding-left: 16px; }

  /* ── Inversion ───────────────────────────── */
  table.items-table { width: 100%; border-collapse: collapse; font-size: 8.5pt; }
  table.items-table th { background: #1a1a2e; color: #fff; padding: 7px 10px; text-align: left; }
  table.items-table th.right, table.items-table td.right { text-align: right; }
  table.items-table td { padding: 6px 10px; border-bottom: 1px solid #eee; vertical-align: top; }
  .item-desc { font-size: 7.5pt; color: #777; margin-top: 2px; }
  .totals-block { margin-top: 14px; display: flex; justify-content: flex-end; }
  .totals-inner { width: 42%; }
  .totals-row { display: flex; justify-content: space-between; padding: 4px 10px; font-size: 9pt; color: #444; border-bottom: 1px solid #f0f0f0; }
  .totals-row.grand { background: #1a1a2e; color: #fff; font-weight: bold; font-size: 11pt; padding: 8px 10px; margin-top: 4px; }
  .payment-note { margin-top: 10px; font-size: 8pt; color: #666; background: #f8f9fc; padding: 8px 12px; border-left: 3px solid #aab; }

  /* ── Aceptacion ──────────────────────────── */
  .acceptance { page-break-before: always; }
  .acceptance-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; margin-top: 24px; }
  .acceptance-party .party-title { font-size: 9.5pt; font-weight: bold; color: #1a1a2e; margin-bottom: 8px; border-bottom: 2px solid #1a1a2e; padding-bottom: 4px; }
  .sig-line { border-bottom: 1px solid #444; height: 44px; margin: 20px 0 8px; }
  .sig-label { font-size: 8pt; color: #555; margin-bottom: 5px; }
</style>

<div class="proposal">

{# ─── 1. PORTADA ────────────────────────────────── #}
<div class="cover">
  <div class="cover-header">
    <div>
      {% if company and company.company_logo %}
      <img src="{{ company.company_logo }}" alt="" style="max-height:52px;max-width:180px;object-fit:contain">
      {% else %}
      <div class="company-name-text">{{ company.company_name if company else '' }}</div>
      {% endif %}
    </div>
    <div class="cover-badge">Propuesta Comercial</div>
  </div>

  <div class="cover-title">
    <h1>{{ fix_lig(doc.proposal_title or doc.name) }}</h1>
    <div class="project-ref">Folio: {{ doc.name }}</div>
  </div>

  <div class="cover-parties">
    <div class="cover-party">
      <div class="party-label">Preparado para</div>
      <div class="party-name">{{ doc.customer_name or doc.party_name or '—' }}</div>
    </div>
    <div class="cover-party">
      <div class="party-label">Preparado por</div>
      <div class="party-name">{{ company.company_name if company else '' }}</div>
      <div class="party-detail">
        {% if owner_name %}{{ owner_name }}<br>{% endif %}
        {% if owner_email %}{{ owner_email }}{% endif %}
      </div>
    </div>
  </div>

  <div class="cover-meta">
    <div><div class="meta-label">Fecha</div><div class="meta-value">{{ frappe.utils.formatdate(doc.transaction_date) }}</div></div>
    <div><div class="meta-label">Vigencia</div><div class="meta-value">{{ frappe.utils.formatdate(doc.valid_till) if doc.valid_till else '—' }}</div></div>
    <div><div class="meta-label">Moneda</div><div class="meta-value">{{ doc.currency }}</div></div>
    <div><div class="meta-label">Version</div><div class="meta-value">1.0</div></div>
  </div>

  <div class="confidential-banner">Confidencial — Solo para uso del destinatario</div>
</div>

{# ─── 2-8. SECCIONES DEL PROPOSAL TEMPLATE ────── #}
{% if doc.proposal_template %}
  {%- set tmpl = frappe.get_doc('Proposal Template', doc.proposal_template) -%}
  {%- set _all_sections = tmpl.sections | sort(attribute='sequence') | list -%}
  {%- set early_sections = _all_sections | selectattr('sequence', 'lt', 500) | list -%}
  {%- set late_sections  = _all_sections | selectattr('sequence', 'ge', 500) | list -%}
  {% for row in early_sections %}
    {%- set ps = frappe.get_doc('Proposal Section', row.proposal_section) -%}
    {%- set s_title = row.custom_title or ps.title or ps.section_name -%}
    {%- set s_content = row.custom_content if row.use_custom_content else ps.content -%}
    {% if ps.enabled and s_content %}
    <div class="section">
      <h2 class="section-title">{{ fix_lig(s_title) }}</h2>
      <div class="section-content">{{ fix_lig(frappe.render_template(s_content, {"doc": doc})) }}</div>
    </div>
    {% endif %}
  {% endfor %}
{% endif %}

{# ─── PLAN DE TRABAJO ───────────────────────────── #}
{% if scope_rows %}
<div class="section">
  <h2 class="section-title">Plan de Trabajo</h2>
  {%- set sorted_rows = scope_rows | sort(attribute='idx') | sort(attribute='sequence') | list -%}
  {%- set phases = [] -%}
  {%- for item in sorted_rows -%}
    {%- if item.phase not in phases -%}{%- set _ = phases.append(item.phase) -%}{%- endif -%}
  {%- endfor -%}
  <table class="deploy-table">
    <thead>
      <tr>
        <th>Actividad</th>
        {% if has_designation %}<th style="width:13%">Perfil</th>{% endif %}
        {% if has_activity %}<th style="width:13%">Tipo</th>{% endif %}
        <th class="right" style="width:8%">Horas</th>
        <th class="right" style="width:7%">Dias</th>
      </tr>
    </thead>
    <tbody>
      {%- set total_h = namespace(value=0) -%}
      {% for phase in phases %}
        {%- set phase_items = sorted_rows | selectattr('phase', 'equalto', phase) | list -%}
        {%- set phase_h = namespace(value=0) -%}
        <tr class="phase-row">
          <td colspan="{{ 3 + (1 if has_designation else 0) + (1 if has_activity else 0) }}">{{ fix_lig(phase or 'Sin fase') }}</td>
        </tr>
        {% for item in phase_items %}
          {%- set h = (item.estimated_hours or 0) | float -%}
          {%- set phase_h.value = phase_h.value + h -%}
          <tr>
            <td class="task-cell">
              <strong>{{ fix_lig(item.title or item.code) }}</strong>
              {% if item.description %}<div class="task-desc">{{ item.description | striptags | truncate(200) }}</div>{% endif %}
            </td>
            {% if has_designation %}<td>{{ item.designation or '' }}</td>{% endif %}
            {% if has_activity %}<td>{{ item.activity_type or '' }}</td>{% endif %}
            <td class="right">{{ '{:g}'.format(h) if h else '' }}</td>
            <td class="right">{{ '{:.2f}'.format(h/8) if h else '' }}</td>
          </tr>
        {% endfor %}
        {%- set total_h.value = total_h.value + phase_h.value -%}
        <tr class="phase-total">
          <td colspan="{{ 1 + (1 if has_designation else 0) + (1 if has_activity else 0) }}" class="right"><em>Total {{ fix_lig(phase or 'Sin fase') }}</em></td>
          <td class="right"><em>{{ '{:g}'.format(phase_h.value) }}h</em></td>
          <td class="right"><em>{{ '{:.2f}'.format(phase_h.value/8) }}d</em></td>
        </tr>
      {% endfor %}
    </tbody>
    <tfoot>
      <tr>
        <td colspan="{{ 1 + (1 if has_designation else 0) + (1 if has_activity else 0) }}" class="right">TOTAL PROYECTO</td>
        <td class="right">{{ '{:g}'.format(total_h.value) }}h</td>
        <td class="right">{{ '{:.2f}'.format(total_h.value/8) }}d</td>
      </tr>
    </tfoot>
  </table>
</div>
{% endif %}

{# ─── ENTREGABLES ──────────────────────────────── #}
{%- set items_with_deliverable = scope_rows | selectattr('deliverable') | list -%}
{% if items_with_deliverable %}
<div class="section">
  <h2 class="section-title">Entregables</h2>
  {% for item in items_with_deliverable | sort(attribute='idx') | sort(attribute='sequence') %}
  <div class="deliverable-item">
    <div class="deliverable-title">{{ fix_lig(item.title or item.code) }}</div>
    <div class="deliverable-body">{{ fix_lig(item.deliverable) }}</div>
  </div>
  {% endfor %}
</div>
{% endif %}

{# ─── INVERSION ────────────────────────────────── #}
{% if doc.items %}
<div class="section">
  <h2 class="section-title">Inversion</h2>
  <table class="items-table">
    <thead>
      <tr>
        <th style="width:4%">#</th>
        <th>Concepto</th>
        <th class="right" style="width:9%">Cant.</th>
        <th class="right" style="width:15%">Precio Unit. {{ doc.currency }}</th>
        <th class="right" style="width:15%">Subtotal {{ doc.currency }}</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>
          {{ fix_lig(item.item_name) }}
          {% if item.description %}<div class="item-desc">{{ item.description | striptags | truncate(140) }}</div>{% endif %}
        </td>
        <td class="right">{{ '{:g}'.format(item.qty) }}</td>
        <td class="right">{{ '{:,.2f}'.format(item.rate) }}</td>
        <td class="right">{{ '{:,.2f}'.format(item.net_amount) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="totals-block">
    <div class="totals-inner">
      <div class="totals-row"><span>Subtotal</span><span>{{ '{:,.2f}'.format(doc.net_total) }} {{ doc.currency }}</span></div>
      {% if doc.discount_amount %}
      <div class="totals-row"><span>Descuento</span><span>&minus;{{ '{:,.2f}'.format(doc.discount_amount) }} {{ doc.currency }}</span></div>
      {% endif %}
      {% if doc.total_taxes_and_charges %}
      <div class="totals-row"><span>Impuestos</span><span>{{ '{:,.2f}'.format(doc.total_taxes_and_charges) }} {{ doc.currency }}</span></div>
      {% endif %}
      <div class="totals-row grand"><span>TOTAL</span><span>{{ '{:,.2f}'.format(doc.grand_total) }} {{ doc.currency }}</span></div>
    </div>
  </div>

  {% if doc.payment_terms_template or doc.payment_schedule %}
  <div class="payment-note">
    <strong>Condiciones de pago:</strong>
    {% if doc.payment_terms_template %} {{ doc.payment_terms_template }}{% endif %}
    {% if doc.payment_schedule %} —
    {% for ps in doc.payment_schedule %}{{ ps.payment_term }}: {{ '{:,.2f}'.format(ps.payment_amount) }} {{ doc.currency }}{% if ps.due_date %} ({{ frappe.utils.formatdate(ps.due_date) }}){% endif %}{% if not loop.last %}, {% endif %}{% endfor %}
    {% endif %}
  </div>
  {% endif %}
</div>
{% endif %}

{# ─── SECCIONES LEGALES / COMERCIALES ──────────── #}
{% if doc.proposal_template and late_sections is defined and late_sections %}
  {% for row in late_sections %}
    {%- set ps = frappe.get_doc('Proposal Section', row.proposal_section) -%}
    {%- set s_title = row.custom_title or ps.title or ps.section_name -%}
    {%- set s_content = row.custom_content if row.use_custom_content else ps.content -%}
    {% if ps.enabled and s_content %}
    <div class="section">
      <h2 class="section-title">{{ fix_lig(s_title) }}</h2>
      <div class="section-content">{{ fix_lig(frappe.render_template(s_content, {"doc": doc})) }}</div>
    </div>
    {% endif %}
  {% endfor %}
{% endif %}

{# ─── CONDICIONES COMERCIALES ─────────────────── #}
{% if doc.terms and not (late_sections is defined and late_sections) %}
<div class="section">
  <h2 class="section-title">Condiciones Comerciales</h2>
  <div class="section-content" style="font-size:9pt">{{ fix_lig(doc.terms) }}</div>
</div>
{% endif %}

{# ─── BLOQUE DE ACEPTACION ────────────────────── #}
<div class="section acceptance">
  <h2 class="section-title">Aceptacion de Propuesta</h2>
  <p style="font-size:9pt;color:#555;margin-bottom:16px">La firma del presente documento indica la aceptacion formal de los terminos, alcance e inversion descritos en esta propuesta.</p>
  <div class="acceptance-grid">
    <div class="acceptance-party">
      <div class="party-title">Cliente</div>
      <div class="sig-line"></div>
      <div class="sig-label">Nombre: {{ doc.customer_name or doc.party_name or '______________________________' }}</div>
      <div class="sig-label">Cargo: ______________________________</div>
      <div class="sig-label">Fecha: ______________________________</div>
    </div>
    <div class="acceptance-party">
      <div class="party-title">{{ company.company_name if company else 'Proveedor' }}</div>
      <div class="sig-line"></div>
      <div class="sig-label">Nombre: {{ owner_name or '______________________________' }}</div>
      <div class="sig-label">Cargo: ______________________________</div>
      <div class="sig-label">Fecha: ______________________________</div>
    </div>
  </div>
</div>

</div>
